\title{A Non-Circular Stone--Weierstrass Density Theorem\\ for the Log-Coordinate Algebra}
\author{Aristotle}
\date{2026-06-24}

\begin{document}
\maketitle

\begin{abstract}
We establish, by an argument carefully constructed to avoid circularity, that the
subalgebra of $C([0,1],\R)$ generated by the single continuous coordinate
$\logcoord(t)=\log(1+t)$ is uniformly dense. Equivalently, its topological closure
is the whole space, and every continuous function on $[0,1]$ is a uniform limit of
polynomials in $\log(1+t)$. The proof rests on exactly two external pillars: the
general Stone--Weierstrass theorem for subalgebras of continuous functions on a
compact Hausdorff space, and elementary analytic properties of the real logarithm
(continuity away from the origin and injectivity on the positive reals). Crucially,
it does \emph{not} invoke any pre-existing universal-approximation statement for
exp--multiply--log (EML) networks; such an appeal would be circular, since a generic
EML universality theorem is precisely the kind of statement one wishes to
instantiate. We isolate the single load-bearing hypothesis---strict monotonicity
(equivalently, injectivity) of the generator---and explain how the result
generalizes to arbitrary strictly monotone generators and to multivariate
log-coordinate algebras on $[0,1]^d$. We also give the concrete form of the
approximants as functions $t\mapsto p(\log(1+t))$ for real polynomials $p$, and
outline a route to quantitative Jackson-type rates via a logarithmic change of
variables.
\end{abstract}

\section{Introduction}

\subsection{EML networks and the universality question}
An \emph{EML network} is a function obtained from a finite alphabet of primitive
operations---the exponential $\exp$, the logarithm $\log$, addition $+$, and
multiplication $\times$---by finite composition. Such networks are natural objects
in computation and learning theory: $\exp$ and $\log$ are the canonical
isomorphisms between additive and multiplicative structure. A foundational
theoretical question is the \emph{expressive power} of EML networks: to what extent
can they approximate arbitrary continuous behavior? Classical
universal-approximation theorems answer analogous questions for sigmoidal or ReLU
networks, but typically in an existential form that obscures \emph{which}
structural features drive universality.

\subsection{The circularity hazard}
A naive route to ``EML networks are universal'' is to assert a generic universality
principle and then specialize it to particular generators. But to \emph{prove}
density of a specific EML-generated algebra by citing a generic ``EML universal
approximation'' theorem is circular: the generic theorem is exactly what one wants
to establish in the first place. The contribution of this paper is to give a
density theorem for a concrete EML generator whose proof depends on \emph{no}
EML-specific universality input---only on classical, independently established
mathematics.

\subsection{Statement of the main result}
Let $C([0,1],\R)$ denote the Banach algebra of continuous real-valued functions on
the compact interval $[0,1]$, equipped with the supremum norm
$\norm{f}=\sup_{t\in[0,1]}|f(t)|$. Define the \emph{log-coordinate}
\[
\logcoord:[0,1]\to\R,\qquad \logcoord(t)=\log(1+t),
\]
and let $\A=\R[\logcoord]$ be the unital $\R$-subalgebra of $C([0,1],\R)$ generated
by $\logcoord$.

\begin{theorem}[Non-circular density]
The closure of $\A$ in $C([0,1],\R)$ is all of $C([0,1],\R)$. Equivalently,
$\overline{\A}=\top$ and $\A$ is dense in the supremum norm.
\end{theorem}

\begin{corollary}[$\varepsilon$-approximation]
For every $F\in C([0,1],\R)$ and every $\varepsilon>0$ there exists $G\in\A$ with
$\norm{F-G}<\varepsilon$.
\end{corollary}

\begin{corollary}[Polynomial-in-log form]
For every $F\in C([0,1],\R)$ and every $\varepsilon>0$ there exists a real
polynomial $p$ with $\norm{F-p\circ\logcoord}<\varepsilon$, i.e.
$\sup_{t\in[0,1]}\bigl|F(t)-p(\log(1+t))\bigr|<\varepsilon$.
\end{corollary}

\section{Definitions and preliminaries}

\subsection{The ambient space}
We work with the compact Hausdorff space $K=[0,1]=\{t\in\R:0\le t\le1\}$, endowed
with the subspace topology inherited from $\R$. As a closed and bounded subset of
$\R$, $K$ is compact and Hausdorff, so $C(K,\R)$ is a unital commutative Banach
algebra under pointwise operations and the supremum norm.

\subsection{Subalgebras, generation, and separation}
A subset $\mathcal{B}\subseteq C(K,\R)$ is a \emph{unital subalgebra} if it
contains the constant functions and is closed under addition, scalar
multiplication, and pointwise multiplication. For a single $g\in C(K,\R)$, the
\emph{generated subalgebra} $\R[g]$ is the smallest unital subalgebra containing
$g$; concretely it equals $\{p\circ g : p\in\R[X]\}$. A family $\mathcal{B}$
\emph{separates points} of $K$ if for all $x\neq y$ in $K$ there is $h\in\mathcal{B}$
with $h(x)\neq h(y)$.

\subsection{The Stone--Weierstrass theorem}
\begin{theorem}[Stone--Weierstrass]
Let $K$ be a compact Hausdorff space and $\mathcal{B}\subseteq C(K,\R)$ a unital
subalgebra that separates points. Then $\mathcal{B}$ is dense in $C(K,\R)$ in the
supremum norm; equivalently, its topological closure is the whole space.
\end{theorem}

\section{The proof}

The argument has four steps: Steps 1--2 establish that $\logcoord$ is a legitimate
continuous, injective coordinate; Step 3 converts injectivity into point separation;
Step 4 applies Stone--Weierstrass.

\subsection{Step 1: continuity}
For $t\in[0,1]$ we have $1+t\ge1>0$, so $\log(1+t)$ is well defined and the argument
$1+t$ stays in the open right half-line where $\log$ is continuous. The map
$t\mapsto1+t$ is continuous and $\log$ is continuous on $(0,\infty)$; their
composition is continuous, so $\logcoord\in C([0,1],\R)$. (Lean: \texttt{one\_add\_pos\_of\_IUnit},
\texttt{logCoord\_continuous}, \texttt{logCoord}, \texttt{logCoord\_apply}.)

\subsection{Step 2: injectivity}
Suppose $x,y\in[0,1]$ with $\log(1+x)=\log(1+y)$. Both $1+x$ and $1+y$ are strictly
positive; the real logarithm is injective on $(0,\infty)$, so $1+x=1+y$ and hence
$x=y$. Equivalently $\logcoord$ is strictly increasing. Thus
$x\neq y\Rightarrow\logcoord(x)\neq\logcoord(y)$. (Lean: \texttt{logCoord\_injective},
using \texttt{Real.log\_injOn\_pos}.)

\subsection{Step 3: point separation}
Let $\A=\R[\logcoord]$. Since $\logcoord\in\A$ and (by Step 2) this single element
distinguishes any pair $x\neq y$, the family $\A$ separates points: take
$h=\logcoord$. (Lean: \texttt{logCoordSubalg}, \texttt{logCoord\_mem\_logCoordSubalg},
\texttt{logCoordSubalg\_separatesPoints}.)

\subsection{Step 4: density via Stone--Weierstrass}
The algebra $\A$ is unital and separates points on the compact Hausdorff space
$[0,1]$, so Stone--Weierstrass gives $\overline{\A}=C([0,1],\R)$. (Lean:
\texttt{logCoordSubalg\_dense}, \texttt{logCoordSubalg\_closure\_eq\_top},
\texttt{logCoordSubalg\_dense\_set}.) \qed

\subsection{Non-circularity, explicitly}
The only imported facts are: (i) Stone--Weierstrass, a theorem about \emph{arbitrary}
point-separating subalgebras with no EML content; and (ii) continuity and
injectivity of $\log$ on the positive reals. No generic EML universal-approximation
statement is ever invoked, so the density of the log-coordinate algebra is derived
from genuinely independent foundations.

\section{The approximants are polynomials in $\log(1+t)$}

\begin{lemma}[Membership characterization]
$G\in\A$ if and only if there exists a real polynomial $p$ with $G=p\circ\logcoord$.
(Lean: \texttt{mem\_logCoordSubalg\_iff}.)
\end{lemma}

\begin{lemma}[Pointwise evaluation]
For every real polynomial $p$ and every $x\in[0,1]$,
$(p\circ\logcoord)(x)=p\bigl(\log(1+x)\bigr)$.
(Lean: \texttt{aeval\_logCoord\_apply}, by induction on $p$.)
\end{lemma}

\begin{theorem}[Explicit polynomial-in-log approximation]
For every $F\in C([0,1],\R)$ and every $\varepsilon>0$ there is a real polynomial
$p$ with $\sup_{t\in[0,1]}\bigl|F(t)-p(\log(1+t))\bigr|<\varepsilon$. (Lean:
\texttt{exists\_poly\_log\_approx}.)
\end{theorem}

\section{Algorithms}

\subsection{Constructive approximant via change of variables}
The substitution $u=\log(1+t)$ is a diffeomorphism of $[0,1]$ onto $[0,\log2]$ with
smooth inverse $t=e^u-1$. Approximating $F(t)$ by $p(\log(1+t))$ on $[0,1]$ is
therefore equivalent to approximating the reshaped function $\widetilde F(u)=F(e^u-1)$
on $[0,\log2]$ by an ordinary polynomial $p(u)$:
\begin{enumerate}
\item Input: continuous target $F$ on $[0,1]$, degree $n$.
\item Reshape: $\widetilde F(u)=F(e^u-1)$ on $[0,\log2]$.
\item Approximate $\widetilde F$ by a degree-$n$ polynomial $p$ (Bernstein on the
  rescaled interval, or least-squares collocation at Chebyshev nodes).
\item Output: the EML network $t\mapsto p(\log(1+t))$.
\item Error: $\sup_t|F(t)-p(\log(1+t))|=\sup_u|\widetilde F(u)-p(u)|\to0$ as $n\to\infty$.
\end{enumerate}

\subsection{Why a Jackson rate is plausible}
Because $u=\log(1+t)$ and $t=e^u-1$ have bounded derivatives on the compact intervals
involved, the modulus of continuity of $\widetilde F$ is controlled by that of $F$ up
to a fixed constant. Classical Jackson estimates on $[0,\log2]$ then transport back to
\[
\norm{F-p\circ\logcoord}\le C\cdot\omega\!\left(F,\tfrac1{\deg p}\right),
\]
where $\omega(F,\cdot)$ is the modulus of continuity of $F$.

\section{Applications}
\begin{itemize}
\item \textbf{Expressivity of EML architectures.} A single monotone log-activation,
  combined with arithmetic, is already a universal approximator on compacta.
\item \textbf{Provenance-safe formal libraries.} Avoiding circular appeals yields a
  reusable, trustworthy building block for formal approximation theory.
\item \textbf{Feature maps and kernels.} $t\mapsto(\log(1+t))^k$ is an explicit
  monotone, universal feature embedding on bounded inputs.
\item \textbf{Numerical surrogates.} The change-of-variables recipe yields cheap
  closed-form surrogates $p(\log(1+t))$.
\end{itemize}

\section{Discussion}
The proof exposes a single load-bearing hypothesis: injectivity (equivalently strict
monotonicity) of the generator. Continuity is needed only to land in $C([0,1],\R)$.
This yields the abstract principle: \emph{any continuous, strictly monotone
$g:[a,b]\to\R$ generates a dense subalgebra of $C([a,b],\R)$}, covering $\exp$,
$\tanh$, softplus, and other monotone EML activations uniformly.

\section{Future work}
\begin{enumerate}
\item \textbf{Quantitative Jackson rate.} Formalize the change-of-variables transport
  of polynomial Jackson estimates, upgrading existence to a degree-explicit bound.
\item \textbf{Multivariate log-coordinate algebras.} Extend to $[0,1]^d$ using
  $\{t\mapsto\log(1+t_i)\}_{i=1}^d$; coordinatewise injectivity gives point separation
  on the cube.
\item \textbf{General strictly monotone generators.} Abstract the load-bearing step
  into a single ``strictly monotone $\Rightarrow$ dense'' lemma.
\item \textbf{Constructive approximants and verified numerics.} Replace the classical
  Stone--Weierstrass step with explicit Bernstein-type constructions enabling
  certified error bounds.
\end{enumerate}

\section{Conclusion}
We have given a non-circular proof that the algebra generated by a single logarithmic
coordinate $t\mapsto\log(1+t)$ is uniformly dense in $C([0,1],\R)$, with approximants
of the explicit form $t\mapsto p(\log(1+t))$. The argument depends only on
Stone--Weierstrass and on the injectivity and continuity of the logarithm, isolating
strict monotonicity as the sole essential property of the generator.

\end{document}

