function FIT_POLY_IN_LOG(F, degree, num_nodes):
    log2 <- log(2)
    for k in 0 .. num_nodes-1:
        cheb <- cos(pi*(k+0.5)/num_nodes)
        u_k  <- 0.5*log2*(cheb + 1)          # node in [0, log 2]
        t_k  <- exp(u_k) - 1                  # inverse change of variable
        v_k  <- F(t_k)
    # assemble normal equations for monomials 1,u,...,u^degree
    A <- (degree+1)x(degree+1) zero matrix
    b <- (degree+1) zero vector
    for each node (u_k, v_k):
        powers <- [u_k^0, ..., u_k^degree]
        for i: b[i] += powers[i]*v_k
        for i,j: A[i][j] += powers[i]*powers[j]
    p <- SOLVE(A, b)                          # Gaussian elimination, partial pivot
    return p                                  # coefficients of p(u)

function EML_APPROXIMANT(p):
